--
-- Estructura de tabla para la tabla `COMPLICATION`
--

CREATE TABLE `COMPLICATION` (
  `complication_id` int NOT NULL,
  `complication_name` varchar(255) NOT NULL,
  `snomed_code` varchar(20) DEFAULT NULL,
  `snomed_term` varchar(255) DEFAULT NULL,
  `icd_code` varchar(20) DEFAULT NULL,
  `icd_term` varchar(255) DEFAULT NULL,
  `description` text,
