--
-- Estructura de tabla para la tabla `SURGICAL_PROCEDURE`
--

CREATE TABLE `SURGICAL_PROCEDURE` (
  `surgical_procedure_id` int NOT NULL,
  `procedure_id` int NOT NULL,
  `episode_id` int NOT NULL,
  `date_time` datetime NOT NULL,
  `expected_end_time` datetime DEFAULT NULL,
  `additional_cost` int DEFAULT NULL,
  `status` enum('Pending','Scheduled','In Progress','Completed','Cancelled') DEFAULT 'Pending',
  `notes` text,
  `operating_room_id` int DEFAULT NULL,
  `ward_id` int DEFAULT NULL,
  `surgical_report` text,
  `anesthesiology_report` text,
  `nursery_report` text,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `patient_id` varchar(50) NOT NULL,
  `asa_score` tinyint DEFAULT NULL COMMENT 'ASA Physical Status Classification 1-6',
  `is_emergency` tinyint(1) DEFAULT '0',
  `time_in_room` datetime DEFAULT NULL,
  `time_incision` datetime DEFAULT NULL,
  `time_closure` datetime DEFAULT NULL,
  `time_out_room` datetime DEFAULT NULL,
  `safety_checklist_data` json DEFAULT NULL COMMENT 'Stores WHO checklist status',
  `blood_loss_ml` int DEFAULT '0' COMMENT 'Pérdida de sangre estimada',
  `post_op_diagnosis` text,
  `post_op_instructions` text,
  `complications` text,
  `priority_level` enum('Elective','Urgent','Emergency') DEFAULT 'Elective',
  `time_intubation` datetime DEFAULT NULL,
  `time_extubation` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Volcado de datos para la tabla `SURGICAL_PROCEDURE`
--

INSERT INTO `SURGICAL_PROCEDURE` (`surgical_procedure_id`, `procedure_id`, `episode_id`, `date_time`, `expected_end_time`, `additional_cost`, `status`, `notes`, `operating_room_id`, `ward_id`, `surgical_report`, `anesthesiology_report`, `nursery_report`, `created_at`, `updated_at`, `deleted_at`, `patient_id`, `asa_score`, `is_emergency`, `time_in_room`, `time_incision`, `time_closure`, `time_out_room`, `safety_checklist_data`, `blood_loss_ml`, `post_op_diagnosis`, `post_op_instructions`, `complications`, `priority_level`, `time_intubation`, `time_extubation`) VALUES
(119, 1, 118, '2025-12-01 09:00:00', NULL, NULL, 'Completed', NULL, 1, 7, 'McBurney incision performed. Appendix identified, inflamed but not perforated. Ligated and removed. Layered closure.', 'Rapid Sequence Induction due to non-fasting status. Propofol 150mg + Rocuronium 50mg. Maintenance with Sevoflurane. Hemodynamically stable. Extubated awake.', 'Pre-op checklist confirmed. Skin prep with Chlorhexidine. Foley catheter inserted. Counts: Sponges x10, Needles x4, Instruments x20 - ALL CORRECT. Specimen \"Appendix\" sent to Pathology. Dressing applied.', '2025-12-07 16:54:00', '2025-12-08 11:59:59', NULL, 'LGP_0001', 2, 1, '2025-12-01 09:00:00', '2025-12-01 09:15:00', '2025-12-01 10:15:00', '2025-12-01 10:30:00', '{\"nurse_checked\": true, \"counts_correct\": true, \"surgeon_checked\": true, \"anesthesia_checked\": true}', 50, NULL, NULL, NULL, 'Urgent', NULL, NULL),
(120, 7, 119, '2025-12-03 14:00:00', NULL, NULL, 'Completed', NULL, 2, 8, 'Successful total knee arthroplasty. Implants cemented. Tourniquet time 85 mins. Good alignment achieved.', 'Spinal anesthesia L3-L4 with Bupivacaine 12.5mg. Sedation with Propofol infusion. BP maintained with Ephedrine boluses. Tourniquet pain managed. Spontaneous breathing throughout.', 'Patient ID confirmed. Time-out performed. Lateral position with supports. Tourniquet Up: 85 mins (250 mmHg). Implant verification: Stryker Triathlon Size 4. Counts correct x2. Drains x1 placed.', '2025-12-07 16:54:11', '2025-12-08 11:59:59', NULL, 'JAV_0001', 3, 0, '2025-12-03 14:00:00', '2025-12-03 14:20:00', '2025-12-03 15:45:00', '2025-12-03 16:00:00', '{\"nurse_checked\": true, \"surgeon_checked\": true, \"anesthesia_checked\": true}', 250, NULL, NULL, NULL, 'Elective', NULL, NULL),
(121, 2, 120, '2025-12-04 11:00:00', NULL, NULL, 'Completed', NULL, 7, 7, 'Laparoscopic cholecystectomy using 4 ports. Gallbladder dissected from liver bed. Cystic duct and artery clipped. Extracted via umbilical port.', 'General Endotracheal Anesthesia (GETA). Easy intubation. OG tube placed. Mild hypotension during pneumoperitoneum, resolved with fluids. PONV prophylaxis given.', 'Supine position. Grounding pad on left thigh. 4 laparoscopic ports used. Specimen \"Gallbladder\" removed intact via Endobag. Fascia closed with Vicryl. Steri-strips applied.', '2025-12-07 16:57:40', '2025-12-08 11:59:59', NULL, 'MRS_0001', 2, 0, '2025-12-04 11:00:00', '2025-12-04 11:20:00', '2025-12-04 12:45:00', '2025-12-04 13:00:00', '{\"nurse_checked\": true, \"counts_correct\": true, \"surgeon_checked\": true, \"anesthesia_checked\": true}', 20, NULL, NULL, NULL, 'Elective', NULL, NULL),
(123, 4, 122, '2025-12-02 08:00:00', NULL, NULL, 'Completed', NULL, 1, 7, 'Open repair of right inguinal hernia with mesh placement (Lichtenstein technique). No complications.', 'Laryngeal Mask Airway (LMA). Propofol TCI. Local infiltration by surgeon (Lidocaine 20ml). Smooth emergence.', 'Shave prep performed. Mesh: Prolene 6x11cm used. Needle count correct. Patient transferred to PACU stable.', '2025-12-08 10:28:16', '2025-12-10 07:37:54', NULL, 'JML_0001', 1, 0, '2025-12-02 08:00:00', '2025-12-02 08:15:00', '2025-12-02 09:15:00', '2025-12-02 09:30:00', '{\"nurse_checked\": true, \"surgeon_checked\": true, \"anesthesia_checked\": true}', 10, NULL, NULL, NULL, 'Elective', NULL, NULL),
(124, 28, 123, '2025-12-06 10:00:00', NULL, NULL, 'Completed', NULL, 2, 8, 'Posterior approach total hip arthroplasty. Acetabular cup and femoral stem cemented. Stability checked. Drain placed.', 'Combined Spinal-Epidural. Tranexamic acid 1g administered. 2 units PRBCs available but not used. Fluid balance +800ml.', 'Lateral decubitus position verified. Padding to pressure points. Implant: Ceramic-on-Poly Acetabular System. Counts correct. Hemovac drain placed.', '2025-12-08 10:28:23', '2025-12-08 11:59:59', NULL, 'MFG_0001', 3, 0, '2025-12-06 10:00:00', '2025-12-06 10:30:00', '2025-12-06 12:45:00', '2025-12-06 13:00:00', '{\"nurse_checked\": true, \"surgeon_checked\": true, \"anesthesia_checked\": true}', 400, NULL, NULL, NULL, 'Elective', NULL, NULL),
(125, 5, 124, '2025-12-01 09:30:00', NULL, NULL, 'Completed', NULL, 7, NULL, 'Phacoemulsification with intraocular lens implantation. Uneventful.', 'Monitored Anesthesia Care (MAC). Midazolam 1mg + Fentanyl 25mcg. Local retrobulbar block by surgeon. Vital signs stable.', 'Eye drops instilled per protocol. Sterile drape applied. Phaco tip check: Pass. IOL Model SN60WF, +21.0D implanted. Eye shield applied.', '2025-12-08 10:30:18', '2025-12-08 11:59:59', NULL, 'THR_0001', 2, 0, '2025-12-01 09:30:00', '2025-12-01 09:45:00', '2025-12-01 11:15:00', '2025-12-01 11:30:00', '{\"nurse_checked\": true, \"surgeon_checked\": true, \"anesthesia_checked\": true}', 5, NULL, NULL, NULL, 'Elective', NULL, NULL),
(128, 9, 127, '2025-12-01 16:00:00', NULL, NULL, 'Completed', NULL, 1, NULL, 'Bilateral tonsillectomy via dissection. Hemostasis secured with cautery. No adenoidectomy.', 'Inhalational induction with Sevoflurane. IV started post-induction. Dexamethasone 4mg given for edema. Deep extubation. No laryngospasm.', 'Patient identification with parents. Mouth gag inserted. Suction setup verified. Throat pack removed at end of case (Confirmed). Counts correct.', '2025-12-08 10:31:23', '2025-12-08 11:59:59', NULL, 'MIF_0011', 1, 0, '2025-12-01 16:00:00', '2025-12-01 16:15:00', '2025-12-01 17:45:00', '2025-12-01 18:00:00', '{\"nurse_checked\": true, \"surgeon_checked\": true, \"anesthesia_checked\": true}', 30, NULL, NULL, NULL, 'Elective', NULL, NULL),
(131, 29, 130, '2025-12-01 12:00:00', NULL, NULL, 'Completed', NULL, 2, 8, 'Arthroscopic repair of supraspinatus tendon using double-row anchors. Subacromial decompression performed.', 'Interscalene block pre-op (Ropivacaine 0.5%). LMA General Anesthesia. Hypotensive anesthesia requested (MAP 60-65) for visualization.', 'Beach chair position. Head secured. Arthroscopy pump pressure 40mmHg. Anchors used: x2 Bio-Composite. Portals sutured with Nylon 3-0.', '2025-12-08 10:37:07', '2025-12-08 11:59:59', NULL, 'SVP_0001', 1, 0, '2025-12-01 12:00:00', '2025-12-01 12:20:00', '2025-12-01 13:45:00', '2025-12-01 14:00:00', '{\"nurse_checked\": true, \"surgeon_checked\": true, \"anesthesia_checked\": true}', 50, NULL, NULL, NULL, 'Elective', NULL, NULL),
(132, 27, 131, '2025-12-01 15:30:00', NULL, NULL, 'Completed', NULL, 3, 3, 'Total abdominal hysterectomy. Uterus enlarged (14 weeks size). Ovaries preserved. No complications.', 'General Anesthesia. EBL 350ml. Urine output 100ml. Post-op pain management: PCA Morphine setup.', 'Foley catheter to gravity. SCDs on legs. Specimen \"Uterus and Cervix\" sent to pathology. Vaginal pack removed (Count verified). Closing count correct.', '2025-12-08 10:37:07', '2025-12-08 11:59:59', NULL, 'MSS_0001', 2, 0, '2025-12-01 15:30:00', '2025-12-01 15:50:00', '2025-12-01 17:40:00', '2025-12-01 18:00:00', '{\"nurse_checked\": true, \"surgeon_checked\": true, \"anesthesia_checked\": true}', 350, NULL, NULL, NULL, 'Elective', NULL, NULL),
(135, 9, 134, '2025-12-02 09:00:00', NULL, NULL, 'Completed', NULL, 6, NULL, 'Bilateral tonsillectomy. Good hemostasis achieved. No adenoidectomy required.', 'Mask induction. Propofol 70mg. Paracetamol IV. Recovered in lateral position.', 'Time-out with mother present. Electrocautery setting: 20 Coag. No complications. Transferred to recovery with O2 mask.', '2025-12-08 10:58:40', '2025-12-08 11:59:59', NULL, 'PIF_0010', 1, 0, '2025-12-02 09:00:00', '2025-12-02 09:20:00', '2025-12-02 10:45:00', '2025-12-02 11:00:00', '{\"nurse_checked\": true, \"surgeon_checked\": true, \"anesthesia_checked\": true}', 20, NULL, NULL, NULL, 'Elective', NULL, NULL),
(136, 10, 135, '2025-12-02 10:30:00', NULL, NULL, 'Completed', NULL, 1, 7, 'Total thyroidectomy. Recurrent laryngeal nerves identified and preserved. Parathyroids preserved.', 'NIM EMG Tube used for nerve monitoring. No muscle relaxant after induction. Extubation after confirming vocal cord movement.', 'Neck roll positioning. Nerve monitor electrode placement verified. Specimen \"Right Thyroid Lobe\" marked for orientation. Drain #1 JP placed.', '2025-12-08 10:58:40', '2025-12-08 12:00:00', NULL, 'IFV_0001', 2, 0, '2025-12-02 10:30:00', '2025-12-02 10:50:00', '2025-12-02 12:15:00', '2025-12-02 12:30:00', '{\"nurse_checked\": true, \"surgeon_checked\": true, \"anesthesia_checked\": true}', 50, NULL, NULL, NULL, 'Elective', NULL, NULL),
(137, 36, 136, '2025-12-02 15:00:00', NULL, NULL, 'Completed', NULL, 3, 3, 'Laparoscopic removal of right ovarian dermoid cyst. Ovary preserved. No spill.', 'General. Trendelenburg position tolerated well. Peak airway pressures normal. Ondansetron 4mg given.', 'Lithotomy position with stirrups. Care taken with nerve compression. Specimen \"Ovarian Cyst\" retrieved in bag. No spill.', '2025-12-08 10:58:40', '2025-12-08 12:00:00', NULL, 'ESD_0001', 1, 0, '2025-12-02 15:00:00', '2025-12-02 15:15:00', '2025-12-02 16:15:00', '2025-12-02 16:30:00', '{\"nurse_checked\": true, \"surgeon_checked\": true, \"anesthesia_checked\": true}', 30, NULL, NULL, NULL, 'Elective', NULL, NULL),
(138, 33, 137, '2025-12-03 09:00:00', NULL, NULL, 'Completed', NULL, 1, 7, 'Laparoscopic assisted sigmoid colectomy. Tumor resected with clear margins. Primary anastomosis performed.', 'General + Epidural catheter T10-T11. Arterial line placed. Hgb stable. Goal directed fluid therapy.', 'Modified lithotomy. EEA Stapler 28mm used. Proximal and distal donuts verified intact. Counts correct x3. Ostomy site marked (not used).', '2025-12-08 11:01:56', '2025-12-08 12:00:00', NULL, 'MFG_0001', 3, 0, '2025-12-03 09:00:00', '2025-12-03 09:30:00', '2025-12-03 11:45:00', '2025-12-03 12:00:00', '{\"nurse_checked\": true, \"surgeon_checked\": true, \"anesthesia_checked\": true}', 150, NULL, NULL, NULL, 'Elective', NULL, NULL),
(139, 4, 138, '2025-12-03 10:00:00', NULL, NULL, 'Completed', NULL, 6, NULL, 'Repair of umbilical hernia. Defect closed with sutures. No mesh used.', 'IV Induction. LMA size 2.5. Local infiltration for post-op analgesia. Awake and crying upon transfer.', 'Supine. Betadine prep. Suture repair with PDS 4-0. Dressing: Steri-strips and Tegaderm.', '2025-12-08 11:01:56', '2025-12-08 12:00:00', NULL, 'MIF_0011', 1, 0, '2025-12-03 10:00:00', '2025-12-03 10:15:00', '2025-12-03 11:15:00', '2025-12-03 11:30:00', '{\"nurse_checked\": true, \"surgeon_checked\": true, \"anesthesia_checked\": true}', 5, NULL, NULL, NULL, 'Elective', NULL, NULL),
(140, 30, 139, '2025-12-03 17:00:00', NULL, NULL, 'Completed', NULL, 4, 5, 'Open reduction and internal fixation (ORIF) of distal radius fracture using volar plate.', 'Bier Block regional anesthesia with Lidocaine 0.5%. Sedation with Midazolam. Tourniquet pain at 45 min, treated with Fentanyl.', 'Arm table setup. C-Arm draped. Implant: Volar Distal Radius Plate (Titanium). Screws x5. Tourniquet time: 55 min. Splint applied.', '2025-12-08 11:01:56', '2025-12-08 12:00:00', NULL, 'SVP_0001', 1, 1, '2025-12-03 17:00:00', '2025-12-03 17:15:00', '2025-12-03 18:45:00', '2025-12-03 19:00:00', '{\"nurse_checked\": true, \"surgeon_checked\": true, \"anesthesia_checked\": true}', 50, NULL, NULL, NULL, 'Emergency', NULL, NULL),
