(173, 7, 172, '2025-12-11 10:14:00', NULL, NULL, 'Completed', NULL, 2, NULL, 'FINDINGS:\n\n\nSPECIMENS:\n\n\nBLOOD LOSS: 0 ml\n\nCOMPLICATIONS:\n', 'Anesthesia Type: General Endotracheal + Femoral Nerve Block.\nASA Score: 3.\nInduction & Maintenance:\nInduction achieved with Propofol (D0026) 100mg and Fentanyl (D0034) 0.45 mg. Intubation was atraumatic.\nAnalgesia: Intra-operative pain managed with Fentanyl (D0034).\nAllergy Management: NSAIDs strictly avoided due to patient history. Post-op pain management initiated with Paracetamol (D0013) 1g IV.\nVitals: Hemodynamics remained stable throughout the procedure. Patient extubated in the OR and transported to recovery breathing spontaneously.\"\n', NULL, '2025-12-11 09:14:25', '2025-12-11 09:19:49', NULL, 'JAV_0001', NULL, 0, '2025-12-11 11:16:44', '2025-12-11 11:17:08', '2025-12-11 11:18:00', '2025-12-11 11:18:07', '{\"anesthesia_checked\": true}', 0, '', NULL, '', 'Elective', '2025-12-11 11:16:56', '2025-12-11 11:18:02');

